        nextCalled = true;
        nextResult = dispatch(i + 1);
        return nextResult;
      };

      const result = middleware(event, middlewareNext);
      return isUnhandledResponse(result)
        ? middlewareNext()
        : typeof (result as PromiseLike<unknown>)?.then === "function"
